async function __ocMintSession(){
  try{
    let url, pw;
    const cands=[];
    if(process.env.OPENCODE_CONFIG_DIR) cands.push(process.env.OPENCODE_CONFIG_DIR+"/opencode/service.json", process.env.OPENCODE_CONFIG_DIR+"/service.json");
    if(process.platform==="win32" && process.env.LOCALAPPDATA) cands.push(process.env.LOCALAPPDATA+"/opencode-data/state/opencode/service.json");
    const xdg=process.env.XDG_STATE_HOME;
    if(xdg) cands.push(xdg+"/opencode/service.json");
    const hm=process.env.HOME||process.env.USERPROFILE;
    if(hm){ cands.push(hm+"/.local/state/opencode/service.json", hm+"/.config/opencode/service.json"); }
    for(const c of cands){
      try{ const j=JSON.parse(require("fs").readFileSync(c,"utf8")); if(j&&j.url){ url=j.url.replace(/\/+$/,""); pw=j.password; break; } }catch(e){}
    }
    if(!url) return undefined;
    const ac=new AbortController(); setTimeout(()=>ac.abort(),3000);
    const r=await fetch(url+"/api/session",{method:"POST",headers:{"Content-Type":"application/json","Authorization":"Basic "+Buffer.from("opencode:"+(pw||"")).toString("base64"),"User-Agent":"opencode/latest/2.0.28/cli"},body:"{}",signal:ac.signal});
    if(!r.ok) return undefined;
    const j=await r.json().catch(()=>null);
    const id=j&&(j.id||(j.data&&j.data.id));
    if(id&&/^ses_[0-9a-f]{12}[0-9A-Za-z]{14}$/.test(id)) return id;
    return undefined;
  }catch(e){ return undefined; }
}
